 "content": "def transform(grid):
    out=[row[:] for row in grid]
    h,w=len(grid),len(grid[0])
    # For each color used as a ray endpoint, extend the nearest same-color
    # edge bar through background, converting the ray to the other marked color.
    # Bars and diagonally arranged markers together indicate rays toward each other.
    # Find uniform edge runs and extend toward the matching marker group.
    for r in range(h):
        for c,v in enumerate(grid[r]):
            if v==1 and (c==0 or grid[r][c-1]!=1):
                end=c
                while end<w and grid[r][end]==1: end+=1
                # A run at the right edge extends left; a run at left extends right.
                if end==w:
                    for x in range(c-1,-1,-1):
                        if grid[r][x]==9: out[r][x]=1
                elif c==0:
                    for x in range(end,w):
                        if grid[r][x]==9: out[r][x]=1
    return out
