    # Horizontal rays point from the 1 seeds toward the nearest 7 anchor.
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 1:
                continue
            # Seed near the left sends right; seed near right sends left.
            direction = 1 if c < w // 2 else -1
            x = c
