 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # A seed 1 on a row containing a vertical 6 bar sends a horizontal ray
    # toward that bar. The seed changes to 4 and intervening background to 1.
    for r, row in enumerate(grid):
        seeds = [c for c, value in enumerate(row) if value == 1]
        bars = [c for c, value in enumerate(row) if value == 6]
        if seeds and bars:
            c = seeds[0]
            target = min(bars, key=lambda x: abs(x - c))
            out[r][c] = 4
            step = 1 if target > c else -1
            for x in range(c + step, target, step):
                if row[x] in (0, 9):
                    out[r][x] = 1

    # At the terminal row of a vertical edge bar, project a horizontal stroke
    # toward the nearest previously aligned 1-bar level. Demos show this at
    # a left-side 6 run's lower endpoint, and the right-side 6 run's upper
    # endpoint can instead project at its lower endpoint as aligned to seed.
    for c in (0, w - 1):
        rows = [r for r in range(h) if grid[r][c] == 6]
        if len(rows) < 2:
            continue
        lo, hi = min(rows), max(rows)
        # Endpoint selected by the location of a 1 seed, if present; otherwise
        # use the lower endpoint, as in the second demo's right edge.
        seed_rows = [r for r, row in enumerate(grid) if 1 in row]
        r = hi
        if c == w - 1 and seed_rows:
            r = hi
        if c == 0 and seed_rows:
            # demo's left bar ray aligns with its lowest end
            r = hi
        if c == 0:
            for x in range(1, w):
                if grid[r][x] in (0, 9):
                    out[r][x] = 1
        else:
            for x in range(c - 1, -1, -1):
                if grid[r][x] in (0, 9):
                    out[r][x] = 1
    return out
