 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # Boundary-connected 1 bars extend across their own rows.
    for r, row in enumerate(grid):
        if row[0] == 1 or row[-1] == 1:
            for c, value in enumerate(row):
                if value == 9:
                    out[r][c] = 1

    marks = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 3]
    if len(marks) < 2:
        return out

    # The endpoints in the diagonal guide are recolored 4.
    for r, c in marks:
        out[r][c] = 4

    # Extend downward from the topmost marker's column, and extend the
    # bottommost marker as a two-column vertical stroke. The guide's right
    # edge is also continued as a two-column vertical stripe.
    top_r, top_c = min(marks)
    bottom_r, bottom_c = max(marks)
    for r in range(top_r + 1, h):
        if grid[r][top_c] not in (0,):
            out[r][top_c] = 3
    for r in range(bottom_r + 1, h):
        for c in (bottom_c, bottom_c + 1):
            if c < w and grid[r][c] != 0:
                out[r][c] = 3
    for r in range(top_r + 1, h):
        for c in (w - 2, w - 1):
            if grid[r][c] != 0:
                out[r][c] = 3
    return out

if __name__ == "__main__":
    d = [[2] * 18 for _ in range(8)]
    d[0][15:] = [0, 0, 0]
    d[1][8] = 3
    d[4][7] = 3
    d[7][6:9] = [0, 0, 0]
    o = transform(d)
    assert o[1][8] == 4 and o[4][7] == 4
    assert o[2][8] == 3 and o[3][8] == 3
    assert o[4][8] == 3 and o[5][7:9] == [3, 3] and o[6][7:9] == [3, 3]
    assert all(o[r][16:18] == [3, 3] for r in range(2, 8))
    assert o[7][6:9] == [0, 0, 0]
    test = [[9] * 22 for _ in range(7)]
    test[0][17:] = [1] * 5
    test[2][2] = 3
    test[3][0] = test[3][3] = 3
    test[4][1] = test[4][4] = 3
    test[6][:5] = [1] * 5
    print(transform(test))
