 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # Transform isolated 1 seed toward a nearby straight boundary marker.
    for r, row in enumerate(grid):
        seeds = [c for c, v in enumerate(row) if v == 1]
        guides = [c for c, v in enumerate(row) if v in (6, 7)]
        if seeds and guides:
            c = seeds[0]
            target = min(guides, key=lambda x: abs(x - c))
            out[r][c] = 4
            step = 1 if target > c else -1
            for x in range(c + step, target, step):
                if row[x] in (0, 9):
                    out[r][x] = 1

    # A 3-marker diagonal guides a horizontal ray of 1s to the right.
    for r, row in enumerate(grid):
        marks = [c for c, v in enumerate(row) if v == 3]
        if marks:
            for c in range(max(marks) + 1, w):
                if row[c] in (0, 9):
                    out[r][c] = 1

    # Edge-attached bars of 1 expand inward across their rows.
    for r, row in enumerate(grid):
        if row[0] == 1 or row[-1] == 1:
            for c, v in enumerate(row):
                if v in (0, 9):
                    out[r][c] = 1
    return out

