 "content": "def transform(grid):
    """Fill the interior between matching 1-segments and diagonal 3 guides."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # For each edge-attached 1 segment, extend the color through its row.
    for r, row in enumerate(grid):
        if row[0] == 1 or row[-1] == 1:
            for c, v in enumerate(row):
                if v == 9:
                    out[r][c] = 1

    # The diagonal 3 pattern is a guide. Recolor its endpoints to 4, then
    # continue each guide column down through the background in 3.
    mark_positions = [(r, c) for r in range(h) for c in range(w)
                      if grid[r][c] == 3]
    if mark_positions:
        for r, c in mark_positions:
            out[r][c] = 4
        cols = sorted({c for _, c in mark_positions})
        for c in cols:
            rows = [r for r, cc in mark_positions if cc == c]
            start = min(rows)
            for r in range(start + 1, h):
                if grid[r][c] == 9:
                    out[r][c] = 3
    return out

