 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    bg = max(set(v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid))

    # Edge-attached bars continue along their row.
    for r, row in enumerate(grid):
        for color in set(row):
            if color != bg and (row[0] == color or row[-1] == color):
                for c, value in enumerate(row):
                    if value == bg:
                        out[r][c] = color

    # Two diagonal guide points define a staircase of the guide color;
    # recolor the endpoints to 4 and fill between adjacent diagonal markers.
    points = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 3]
    for r, c in points:
        out[r][c] = 4
    for (r1, c1), (r2, c2) in zip(points, points[1:]):
        dr = 1 if r2 > r1 else -1
        dc = 1 if c2 > c1 else -1
        r, c = r1 + dr, c1 + dc
        while r != r2 and c != c2:
            if grid[r][c] == bg:
                out[r][c] = 3
            r += dr
            c += dc
    return out

if __name__ == "__main__":
    g = [[9] * 22 for _ in range(7)]
    g[0][17:] = [1] * 5
    g[2][2] = 3
    g[3][0] = g[3][3] = 3
    g[4][1] = g[4][4] = 3
    g[6][:5] = [1] * 5
    print(transform(g))
